const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np,json
D=json.load(open('/app/data/calibration.json'))
def vals(e,g=1.1):
 b,c,w=e['temperature'],e['contrast'],e['wavenumber']; x=np.linspace(0,2*np.pi,100000,endpoint=False); T=b*(1+c*np.cos(w*x)); Tp=-b*c*w*np.sin(w*x)
 u=np.mean(Tp**2/(2*g*T)); p=np.sum(Tp**2/(2*g*T)*1/T)/np.sum(1/T)
 # other common: uniform T'^2/(2 gamma T), p1/T
 return u,p
for e in [D[i]['input'] for i in range(0,12)]: print(e, vals(e))
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":5000});
